/* Offline PDF report, using the same typography and page frame as natal-chart. */
(function(root){
'use strict';
let ready;
function script(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('Не удалось загрузить PDF-модуль'));document.head.append(s);});}
async function prepare(){if(!ready)ready=(async()=>{await script('vendor/pdfmake.min.js');await script('vendor/vfs_fonts.js');for(const name of ['PT_Serif-Web-Regular.ttf','PT_Serif-Web-Bold.ttf','DejaVuSans.ttf']){const response=await fetch('vendor/'+name);if(!response.ok)throw Error('Не удалось загрузить шрифт');const bytes=new Uint8Array(await response.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));pdfMake.vfs[name]=btoa(binary);}pdfMake.fonts={Roboto:{normal:'Roboto-Regular.ttf',bold:'Roboto-Medium.ttf',italics:'Roboto-Italic.ttf',bolditalics:'Roboto-MediumItalic.ttf'},Serif:{normal:'PT_Serif-Web-Regular.ttf',bold:'PT_Serif-Web-Bold.ttf'},Glyph:{normal:'DejaVuSans.ttf',bold:'DejaVuSans.ttf'}};})().catch(e=>{ready=null;throw e;});return ready;}
function frame(){return {canvas:[{type:'rect',x:26,y:26,w:543.28,h:789.89,lineWidth:.9},{type:'rect',x:30.5,y:30.5,w:534.28,h:780.89,lineWidth:.35,lineColor:'#555'},...[ [26,26],[569.28,26],[26,815.89],[569.28,815.89] ].map(([x,y])=>({type:'polyline',points:[{x,y:y-4},{x:x+4,y},{x,y:y+4},{x:x-4,y}],closePath:true,lineWidth:.8}))]};}
function definition(c,svg,helpers){const {formatLon,localTime,placeLabel,H,R}=helpers;const date=localTime(c.date,c.input.offset);const heading=text=>({text,style:'h2'});const paragraph=text=>({text:String(text),margin:[0,0,0,8]});const table=(headers,rows,widths)=>({table:{headerRows:1,widths,body:[headers.map(text=>({text,bold:true,fillColor:'#f0f0f0'})),...rows]},layout:'lightHorizontalLines',fontSize:9,margin:[0,8,0,14]});
 const content=[{text:'Х О Р А Р Н А Я   К А Р Т А',font:'Serif',bold:true,fontSize:21,alignment:'center',margin:[0,24,0,18]},{text:c.input.question,font:'Serif',fontSize:16,alignment:'center',margin:[0,0,0,16]}, {text:date,alignment:'center',fontSize:10},{text:c.input.place?placeLabel(c.input.place):'Координаты введены вручную',alignment:'center',fontSize:10,margin:[0,5,0,4]}, {text:`${c.input.lat}°, ${c.input.lon}° · ${c.input.place?.timezone||'Ручной UTC'} · ${ {regio:'Региомонтан',equal:'Равнодомная',whole:'Цельнознаковая'}[c.input.system]||c.input.system}`,alignment:'center',fontSize:9}];
 if(svg)content.push({svg,width:420,alignment:'center',margin:[0,12,0,10]});
 content.push({text:'Карта момента · положения планет · подробный разбор',alignment:'center',fontSize:10},{text:'Астрологическая интерпретация не является научно подтверждённым прогнозом.',alignment:'center',fontSize:9,color:'#555',margin:[0,12,0,0]}, {text:'Разбор вопроса',style:'h2',pageBreak:'before'},heading(c.verdict),paragraph(c.explanation),table(['Роль','Управитель','Положение','Дом'],[[c.analysis?.actorHouse&&c.analysis.actorHouse!==1?'Участник ('+c.analysis.actorHouse+' дом)':'Вы',H.names[c.querent],formatLon(c.planets[c.querent].lon),String(c.planets[c.querent].house)],['Предмет вопроса',H.names[c.subject],formatLon(c.planets[c.subject].lon),String(c.planets[c.subject].house)]],['*','*','*',30]),heading('Рецепции'),paragraph(c.receptions.length?c.receptions.join('\n'):'Рецепций по обители и экзальтации между управителями нет.'));
 const simple=typeof HorarSimple!=='undefined'?HorarSimple:typeof module!=='undefined'?require('./simple'):null;
 if(simple){const easy=simple.explain(c),easyContent=[{text:'Понятный разбор',style:'h2',pageBreak:'before'},heading(easy.title),paragraph(easy.summary)];for(const section of easy.sections)easyContent.push({unbreakable:true,stack:[heading(section.title),paragraph(section.paragraphs[0])]},...section.paragraphs.slice(1).map(paragraph));const idx=content.findIndex(x=>x.text==='Разбор вопроса');content[idx].text='Технический разбор';content.splice(idx,0,...easyContent);}
 for(const text of c.notices)content.push(paragraph(text));
 for(const step of R.explain(c))content.push(heading(step.title),{text:'РАСЧЁТ',style:'label'},paragraph(step.fact),{text:'ТРАКТОВКА',style:'label'},paragraph(step.meaning),{text:'ОГРАНИЧЕНИЕ',style:'label'},paragraph(step.limit));
 content.push({text:'Положения и аспекты',style:'h2',pageBreak:'before'},table(['Планета','Положение','Дом','Состояние'],c.planets.map(p=>[p.name,formatLon(p.lon),String(p.house),(p.retro?'Ретроградная. ':'Прямая. ')+p.dignity.join(', ')]),[60,100,25,'*']),heading('Аспекты в орбисе'));
 if(c.pairs.length)content.push(table(['Планеты','Аспект','Орбис','Движение'],c.pairs.map(a=>[`${H.names[a.i]} — ${H.names[a.j]}`,a.name,a.orb.toFixed(2)+'°',H.phaseLabel(a.phase)]),['*',75,40,95]));else content.push(paragraph('Мажорных аспектов в выбранных орбисах нет.'));
 content.push({text:'Куспиды домов',style:'h2',pageBreak:'before'},table(['Дом','Положение'],c.cusps.map((l,i)=>[String(i+1),formatLon(l)]),[60,'*']),heading('Следующие аспекты Луны'));
 if(c.lunar){if(c.lunar.void)content.push(paragraph('Луна без курса по принятому определению. Это не самостоятельный ответ на вопрос.'));for(const e of c.lunar.events)content.push(paragraph(`${e.name} — ${H.names[e.i]}: ${localTime(e.utc,c.input.offset)}`));content.push(paragraph('Выход из знака: '+localTime(c.lunar.ingress,c.input.offset)));}else content.push(paragraph('Не удалось рассчитать будущие аспекты Луны.'));
 content.push(heading('Пределы интерпретации'),paragraph(c.analysis?c.analysis.limits:'Расширенные правила для этой старой карты не включены.'));
 return {pageSize:'A4',pageMargins:[56,64,56,58],background:frame,header:n=>n>1?{text:'ХОРАРНАЯ КАРТА · '+date,margin:[56,40,56,0],fontSize:8,color:'#555'}:null,footer:(n,total)=>({text:`Хорар · ${n} / ${total}`,alignment:'right',margin:[56,8,56,0],fontSize:8}),info:{title:'Хорар — '+c.input.question,author:'Хорар'},defaultStyle:{font:'Roboto',fontSize:10,lineHeight:1.35,color:'#111'},styles:{h2:{font:'Serif',bold:true,fontSize:15,margin:[0,16,0,8]},label:{fontSize:8,bold:true,color:'#555',margin:[0,4,0,4]}},content};}
async function save(c,svg,helpers,returnData=false){await prepare();const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');for(const el of clone.querySelectorAll('text'))el.setAttribute('font-family','Glyph');const xml=new XMLSerializer().serializeToString(clone);const pdf=pdfMake.createPdf(definition(c,xml,helpers));if(returnData)return await new Promise(resolve=>pdf.getBase64(resolve));const name='Horar-'+new Date(c.date).toISOString().slice(0,10)+'.pdf';if(root.Android?.savePdf){const data=await new Promise(resolve=>pdf.getBase64(resolve));root.Android.savePdf(name,data);}else pdf.download(name);}
root.HorarPDF={definition,save};if(typeof module!=='undefined')module.exports=root.HorarPDF;
})(typeof window==='undefined'?globalThis:window);
